"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[81863],{3331:(e,n,i)=>{i.d(n,{R:()=>s,x:()=>a});var r=i(36672);const t={},o=r.createContext(t);function s(e){const n=r.useContext(o);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:s(e.components),r.createElement(o.Provider,{value:n},e.children)}},81255:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>a,default:()=>c,frontMatter:()=>s,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"De-Stressing Booking.com","source":"@site/i18n/nl/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/nl/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nl/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17 april 2023","top_news":"De-Stressing Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/nl/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/nl/2023/04/16"}}');var t=i(23420),o=i(3331);const s={localized_date:"17 april 2023",top_news:"De-Stressing Booking.com"},a="2023-04-17",d={},l=[{value:"De-Stressing Booking.com",id:"de-stressing-bookingcom",level:2},{value:"Ik heb Stable Diffusion en Dreambooth gebruikt om een kunstportret van mijn hond te maken.",id:"ik-heb-stable-diffusion-en-dreambooth-gebruikt-om-een-kunstportret-van-mijn-hond-te-maken",level:2},{value:"AT&amp;T Wireless traffic shaping maakt sommige websites blijkbaar onbruikbaar.",id:"att-wireless-traffic-shaping-maakt-sommige-websites-blijkbaar-onbruikbaar",level:2},{value:"Future Blues - Emily&#39;s Cowboy Bebop Pagina (1999)",id:"future-blues---emilys-cowboy-bebop-pagina-1999",level:2},{value:"Vaatwasser Zalm",id:"vaatwasser-zalm",level:2},{value:"Pico3D: Open World 3D Game Engine voor het PicoSystem (RP2040 Microcontroller)",id:"pico3d-open-world-3d-game-engine-voor-het-picosystem-rp2040-microcontroller",level:2},{value:"Wayback: Zelf gehoste archiveringsdienst ge\xefntegreerd met Internet Archive",id:"wayback-zelf-gehoste-archiveringsdienst-ge\xefntegreerd-met-internet-archive",level:2},{value:"De snelste wiskundige zetbibliotheek voor het web",id:"de-snelste-wiskundige-zetbibliotheek-voor-het-web",level:2},{value:"&#39;Algebra voor niemand&#39; mislukt in San Francisco",id:"algebra-voor-niemand-mislukt-in-san-francisco",level:2},{value:"FSF bekritiseert Google voor het schrappen van JPEG-XL in Chrome",id:"fsf-bekritiseert-google-voor-het-schrappen-van-jpeg-xl-in-chrome",level:2}];function h(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,t.jsx)(n.h2,{id:"de-stressing-bookingcom",children:"De-Stressing Booking.com"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Origineel"}),'.\nDe schrijver deelt een opiniestuk over het overmatig gebruik van overredingstactieken op e-commerce websites, met name Booking.com, en introduceert hun Chrome Extension, "De-stresser," die stressverwekkende berichten en meldingen van Booking.com verwijdert, waardoor gebruikers een aangenamere ervaring krijgen. Door persuasion tags te verbergen en het taalgebruik positiever te laten klinken, zorgt de De-stresser voor een rustigere en meer ontspannen boekingservaring voor gebruikers. De extensie is nu live en beschikbaar voor gebruik op Booking.com.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com wordt bekritiseerd vanwege het gebruik van verkoopstrategie\xebn onder hoge druk, zoals urgentieberichten en pop-ups die gebruikers kunnen afschrikken. Critici beweren dat deze aanpak prioriteit geeft aan kortetermijncijfers boven klantentrouw op lange termijn. Gebruikers melden dat ze manieren hebben gevonden om deze tactieken te omzeilen, waaronder het gebruik van extensies om ze te blokkeren of te filteren. Ondertussen discussi\xebren Discussion Service-gebruikers over de verdiensten van A/B-tests, waarbij sommigen wijzen op het potentieel om "donkere patronen" op websites te cre\xebren. Ondanks deze zorgen blijven veel gebruikers boekingsaggregators zoals Booking.com en Expedia gebruiken, voor het gemak of omdat ze gunstige prijzen en annuleringsvoorwaarden bieden. Sommige deskundigen waarschuwen dat rechtstreeks bij hotels boeken betere mogelijkheden voor geschillenbeslechting kan bieden, terwijl anderen erop wijzen dat de commissietarieven voor boekingssites sterk kunnen vari\xebren, afhankelijk van het hotel. Niettemin kunnen loyaliteitsprogramma\'s van hotels aanzienlijke voordelen bieden aan frequente reizigers.']}),"\n",(0,t.jsx)(n.h2,{id:"ik-heb-stable-diffusion-en-dreambooth-gebruikt-om-een-kunstportret-van-mijn-hond-te-maken",children:"Ik heb Stable Diffusion en Dreambooth gebruikt om een kunstportret van mijn hond te maken."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Origineel"}),".\nHet artikel bespreekt het gebruik van Stable Diffusion en Dreambooth AI-technieken om een hoogwaardig geschilderd portret van een hond te maken. De auteur deelt zijn volledige workflow en geeft gedetailleerde instructies voor het trainen van een Dreambooth-model op foto's van zijn hond. Het artikel bespreekt ook het gebruik van upscaling om kleine afbeeldingen op te blazen voor hoogwaardige afdrukken en introduceert Stable Diffusion als een game-changer voor de wereld van tekst-naar-beeld generatieve kunst."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nEen Discussion Service-gebruiker gebruikte Stable Diffusion en Dreambooth om een kunstportret van zijn hond te maken, terwijl in het commentaar de weerstand tegen AI-kunst en debatten over auteursrecht en eerlijk gebruik werden besproken. Het gebruik van generatieve AI voor kunst roept ethische vragen op over auteursrecht en fair use, en de meningen hierover zijn verdeeld. Sommigen bekritiseerden Stable Diffusion voor het gebruik van onbetaalde gestolen kunstwerken als trainingsgegevens, terwijl anderen de technologie en het potentieel voor verdere innovatie op dit gebied prezen."]}),"\n",(0,t.jsx)(n.h2,{id:"att-wireless-traffic-shaping-maakt-sommige-websites-blijkbaar-onbruikbaar",children:"AT&T Wireless traffic shaping maakt sommige websites blijkbaar onbruikbaar."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Origineel"}),'.\nAT&T\'s "onbeperkte" 100Mbit plan met 50GB voor geprioriteerde data kan op agressieve wijze traffic shaping veroorzaken, waardoor sommige websites onbruikbaar zijn, terwijl een test aantoonde dat een Verizon SIM-kaart niet hetzelfde probleem had. Akamai verkeer toont bewijs van opzettelijke manipulatie van de TCP stroom. Traffic shaping treft alleen data-only accounts op zakelijke accounts.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless beperkt naar verluidt IP-adressen voor sommige videostreamingsites, waardoor sommige websites onbruikbaar worden en er discrepanties ontstaan in internetsnelheidstests. Gebruikers hebben oplossingen voorgesteld zoals het indienen van een FCC-klacht, het gebruik van een VPN om de beperking te omzeilen of het proberen van een andere APN. Sommige respondenten zijn sceptisch over de kwade bedoelingen achter de beperking, terwijl anderen oplossingen voorstellen zoals snelheidsbeperkingen of het verlagen van de videokwaliteit om de toewijzing van gegevens te behouden."]}),"\n",(0,t.jsx)(n.h2,{id:"future-blues---emilys-cowboy-bebop-pagina-1999",children:"Future Blues - Emily's Cowboy Bebop Pagina (1999)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://futureblues.com/",children:"Origineel"}),".\nSorry, er is geen tekst die ik kan samenvatten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nDiscussion Service-gebruikers hebben heimwee naar de originele en creatieve ontwerpen van klassieke websites, die in contrast staan met de gestandaardiseerde, lawaaierige en gemonetariseerde aard van moderne websites, wat wijst op een verlangen naar meer artistieke, op individualiteit gerichte medialandschappen. Er ontstaan discussiepunten waarin Wikipedia en Fandom worden vergeleken, en het onderscheid tussen mobiele en desktop-only sites, en het ontwerp van de website wekt zowel nostalgie als verwondering over de lange levensduur ervan. In het algemeen biedt het bericht een blik op de dierbare herinneringen van gebruikers aan het vroege internet en biedt het een platform voor discussie over de huidige staat van het web."]}),"\n",(0,t.jsx)(n.h2,{id:"vaatwasser-zalm",children:"Vaatwasser Zalm"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Origineel"}),".\nAfwasmachinezalm is een visgerecht dat wordt bereid door stukken zalm in minstens twee lagen aluminiumfolie te wikkelen en in de vaatwasser te plaatsen tijdens het was- en droogprogramma. De methode werd voor het eerst gedemonstreerd in de VS door Vincent Price in 1975 en is sindsdien in verschillende media verschenen. Er bestaat echter bezorgdheid over de consistentie van de temperaturen in vaatwasmachines, wat kan leiden tot onvolledige garing en mogelijke gezondheidsrisico's."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nEen Hacker News artikel over het koken van zalm in een vaatwasser ontketent een debat over de veiligheid van de kookmethode, met gebruikers in de voedselveiligheidsindustrie die beweringen in het onderzoek van een YouTuber tegenspreken. Hoewel de veiligheid van koken in de vaatwasser van meerdere factoren afhangt, is ten minste 63\xb0C gedurende 15 seconden nodig om bacteri\xebn in zalm te doden."]}),"\n",(0,t.jsx)(n.h2,{id:"pico3d-open-world-3d-game-engine-voor-het-picosystem-rp2040-microcontroller",children:"Pico3D: Open World 3D Game Engine voor het PicoSystem (RP2040 Microcontroller)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Origineel"}),".\nDe Pico3D game engine gebruikt de tweede kern van de RP2040 als een speciale rasterizer/GPU om een compleet open wereld 3D spel te draaien op een microcontroller van 1 dollar. De engine bevat een kleine stad en buitenwijken met schietbare zombies, met Blender tutorials beschikbaar voor het cre\xebren van spelwerelden. De simulatie van de engine bevat momenteel 50 NPC's en 50 zombies tegelijk, met rendering geoptimaliseerd met afstand en view frustum culling."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nEen nieuwe 3D game engine genaamd Pico3D is ontwikkeld voor de RP2040 microcontroller met een 120x120px display, en het ontbreekt aan voldoende geheugen en video RAM, maar heeft een uniforme API. Hackers zijn enthousiast over creatieve manieren om de Pico/RP2040 te gebruiken, en de unieke toepassing van RAM-chips in de framebuffer maakt dit artikel opvallend op de tech-site."]}),"\n",(0,t.jsx)(n.h2,{id:"wayback-zelf-gehoste-archiveringsdienst-ge\xefntegreerd-met-internet-archive",children:"Wayback: Zelf gehoste archiveringsdienst ge\xefntegreerd met Internet Archive"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/wabarc/wayback",children:"Origineel"}),".\nWayback is een zelf gehoste archiveringstool die tot doel heeft webpagina's in tijdscapsules op te nemen. Het is gratis, open-source, cross-platform, en maakt een gemakkelijkere integratie mogelijk met verschillende platformen, waaronder het Internet Archive, archive.today, IPFS, en Telegraph. Het biedt ook verschillende installatiemogelijkheden, waaronder via GitHub, Snapcraft, APT, RPM en Homebrew."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nDe Wabarc self-hosted archiveringsdienst maakt snapshots van webpagina\'s in "tijdcapsules" en slaat bestanden op voor offline gebruik; Discussion Service-gebruikers bekritiseren echter de onduidelijke README en het gebrek aan documentatie. Andere soortgelijke projecten zijn ArchiveBox, Shiori, DiskerNet en SingleFile; HTTrack Website Copier wordt aanbevolen voor het lokaal downloaden van een hele website, terwijl Browsertrix/Brozzler crawlt met headless browsers voor nauwkeurigheid. Een Discussion Service-gebruiker beveelt The Old Net aan voor het doorzoeken van oude/moderne browsers zonder JS, en de repo waarnaar wordt verwezen heeft meer duidelijkheid nodig over deelbaarheid en vastgestelde archiveringsstandaarden.']}),"\n",(0,t.jsx)(n.h2,{id:"de-snelste-wiskundige-zetbibliotheek-voor-het-web",children:"De snelste wiskundige zetbibliotheek voor het web"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://katex.org/",children:"Origineel"}),".\nKaTeX is een snelle wiskundige zetbibliotheek voor het web die een opmaak van drukkwaliteit biedt op basis van Donald Knuth's TeX, geen afhankelijkheden heeft en gemakkelijk kan worden gebundeld met websitebronnen voor rendering aan de serverkant met behulp van Node.js. De eenvoudige API rendert effici\xebnt wiskundige expressies, zelfs op pagina's met meerdere expressies, zonder beperking van browser of omgeving, en is open source onder de MIT-licentie."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, de snelste bibliotheek voor het zetten van wiskunde op het web, biedt geen ondersteuning voor diagrammen, waardoor het voor sommige wiskundigen ongeschikt is, terwijl MathJax en AsciiMath beide soortgelijke projecten hebben. Er is een vergelijkingswebsite gedeeld, en de prestaties en het praktische nut van het aanpassen van markup aan verschillende contexten worden besproken door gebruikers van Hacker News."]}),"\n",(0,t.jsx)(n.h2,{id:"algebra-voor-niemand-mislukt-in-san-francisco",children:"'Algebra voor niemand' mislukt in San Francisco"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Origineel"}),'.\nVolgens een studie van Stanford-professoren heeft het "Algebra voor niemand"-beleid van het San Francisco Unified schooldistrict de prestaties van zwarte en Latijns-Amerikaanse leerlingen in wiskunde voor gevorderden niet verbeterd. Het besluit om algebra uit te stellen tot de negende klas en laag- en hoogpresterende leerlingen in dezelfde klassen te plaatsen, hielp de laagpresterende leerlingen niet en maakte het voor hoogpresterende leerlingen moeilijker om te slagen. Gezinnen die het zich kunnen veroorloven zijn overgestapt op online cursussen of priv\xe9scholen. Een groep ouders heeft een rechtszaak aangespannen tegen het district, omdat zij beweren dat de staatswet inzake gelijke toegang tot gevorderde wiskunde wordt overtreden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nEr is kritiek op het beleid van San Francisco om algebra uit te stellen tot de negende klas en lage, gemiddelde en hoge presteerders in dezelfde klassen te plaatsen. Sommige Discussion Service-gebruikers stellen voor academische en buitenschoolse successen te stimuleren door ze te koppelen aan een financi\xeble beloning, terwijl anderen stellen dat het subsidi\xebren van hoger onderwijs via kredietsystemen om later de universiteit te betalen een betere oplossing zou zijn. Er zijn discussies over het nut van traditioneel wiskundeonderwijs en de doeltreffendheid van meer financiering om de klassen te verkleinen, waarbij sommige gebruikers voorstellen om wiskunde te onderwijzen via technische problemen en de voordelen van online onderwijs."]}),"\n",(0,t.jsx)(n.h2,{id:"fsf-bekritiseert-google-voor-het-schrappen-van-jpeg-xl-in-chrome",children:"FSF bekritiseert Google voor het schrappen van JPEG-XL in Chrome"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Origineel"}),".\nDe Free Software Foundation bekritiseert de beslissing van Google om JPEG-XL niet langer te ondersteunen in Chrome en wijst op de noodzaak van browserkeuze en vrije mediaformaten. Ondanks het tumult van de gemeenschap gingen de ingenieurs van Google toch door met de beslissing, die een van de top-onderwerpen in de geschiedenis van het Chromium-project blijft. Gebruikers hebben veel steun getoond voor JPEG-XL, maar Google's focus op controle boven vrijheid lijkt de overhand te hebben."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle krijgt kritiek van de Free Software Foundation voor het stopzetten van de ondersteuning voor JPEG-XL in Chrome, ondanks de toepassing ervan door grote beeldbewerkers. Sommige gebruikers stellen dat oudere formaten zoals PNG en JPEG volstaan, terwijl anderen de voorkeur geven aan codecs zoals AVIF voor video. Het debat draait om de levensvatbaarheid en adoptie van nieuwe afbeeldingsformaten in het ecosysteem, waarbij de industrie ondersteuning en interesse in JPEG-XL heeft opgemerkt, maar de adoptie afhankelijk is van de ondersteuning door alle grote browsers."]})]})}function c(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}}}]);